17	package org.springframework.boot.context.logging;
18	
19	import java.io.FileNotFoundException;
20	import java.util.Collections;
21	import java.util.List;
22	import java.util.Map;
23	import java.util.concurrent.atomic.AtomicBoolean;
24	import java.util.function.BiConsumer;
25	
26	import org.apache.commons.logging.Log;
27	import org.apache.commons.logging.LogFactory;
28	import org.jspecify.annotations.Nullable;
29	
30	import org.springframework.beans.factory.config.ConfigurableListableBeanFactory;
31	import org.springframework.boot.SpringApplication;
32	import org.springframework.boot.context.event.ApplicationEnvironmentPreparedEvent;
33	import org.springframework.boot.context.event.ApplicationFailedEvent;
34	import org.springframework.boot.context.event.ApplicationPreparedEvent;
35	import org.springframework.boot.context.event.ApplicationStartingEvent;
36	import org.springframework.boot.context.properties.bind.Bindable;
37	import org.springframework.boot.context.properties.bind.Binder;
38	import org.springframework.boot.context.properties.source.ConfigurationPropertyName;
39	import org.springframework.boot.logging.LogFile;
40	import org.springframework.boot.logging.LogLevel;
41	import org.springframework.boot.logging.LoggerGroup;
42	import org.springframework.boot.logging.LoggerGroups;
43	import org.springframework.boot.logging.LoggingInitializationContext;
44	import org.springframework.boot.logging.LoggingSystem;
45	import org.springframework.boot.logging.LoggingSystemProperties;
46	import org.springframework.context.ApplicationContext;
47	import org.springframework.context.ApplicationEvent;
48	import org.springframework.context.ApplicationListener;
49	import org.springframework.context.ConfigurableApplicationContext;
50	import org.springframework.context.SmartLifecycle;
51	import org.springframework.context.event.ContextClosedEvent;
52	import org.springframework.context.event.GenericApplicationListener;
53	import org.springframework.core.Ordered;
54	import org.springframework.core.ResolvableType;
55	import org.springframework.core.env.ConfigurableEnvironment;
56	import org.springframework.core.env.Environment;
57	import org.springframework.core.log.LogMessage;
58	import org.springframework.util.Assert;
59	import org.springframework.util.LinkedMultiValueMap;
60	import org.springframework.util.MultiValueMap;
61	import org.springframework.util.StringUtils;
62	
63	/**
64	 * An {@link ApplicationListener} that configures the {@link LoggingSystem}. If the
65	 * environment contains a {@code logging.config} property it will be used to bootstrap the
66	 * logging system, otherwise a default configuration is used. Regardless, logging levels
67	 * will be customized if the environment contains {@code logging.level.*} entries and
68	 * logging groups can be defined with {@code logging.group}.
69	 * <p>
70	 * Debug and trace logging for Spring, Tomcat, Jetty and Hibernate will be enabled when
71	 * the environment contains {@code debug} or {@code trace} properties that aren't set to
72	 * {@code "false"} (i.e. if you start your application using
73	 * {@literal java -jar myapp.jar [--debug | --trace]}). If you prefer to ignore these
74	 * properties you can set {@link #setParseArgs(boolean) parseArgs} to {@code false}.
75	 * <p>
76	 * By default, log output is only written to the console. If a log file is required, the
77	 * {@code logging.file.path} and {@code logging.file.name} properties can be used.
78	 * <p>
79	 * Some system properties may be set as side effects, and these can be useful if the
80	 * logging configuration supports placeholders (i.e. log4j or logback):
81	 * <ul>
82	 * <li>{@code LOG_FILE} is set to the value of path of the log file that should be written
83	 * (if any).</li>
84	 * <li>{@code PID} is set to the value of the current process ID if it can be determined.
85	 * </li>
86	 * </ul>
87	 *
88	 * @author Dave Syer
89	 * @author Phillip Webb
90	 * @author Andy Wilkinson
91	 * @author Madhura Bhave
92	 * @author HaiTao Zhang
93	 * @since 2.0.0
94	 * @see LoggingSystem#get(ClassLoader)
95	 */
96	public class LoggingApplicationListener implements GenericApplicationListener {
97	
98		private static final ConfigurationPropertyName LOGGING_LEVEL = ConfigurationPropertyName.of("logging.level");
99	
100		private static final ConfigurationPropertyName LOGGING_GROUP = ConfigurationPropertyName.of("logging.group");
101	
102		private static final Bindable<Map<String, LogLevel>> STRING_LOGLEVEL_MAP = Bindable.mapOf(String.class,
103				LogLevel.class);
104	
105		private static final Bindable<Map<String, List<String>>> STRING_STRINGS_MAP = Bindable
106			.of(ResolvableType.forClassWithGenerics(MultiValueMap.class, String.class, String.class).asMap());
107	
108		/**
109		 * The default order for the LoggingApplicationListener.
110		 */
111		public static final int DEFAULT_ORDER = Ordered.HIGHEST_PRECEDENCE + 20;
112	
113		/**
114		 * The name of the Spring property that contains a reference to the logging
115		 * configuration to load.
116		 */
117		public static final String CONFIG_PROPERTY = "logging.config";
118	
119		/**
120		 * The name of the Spring property that controls the registration of a shutdown hook
121		 * to shut down the logging system when the JVM exits.
122		 * @see LoggingSystem#getShutdownHandler
123		 */
124		public static final String REGISTER_SHUTDOWN_HOOK_PROPERTY = "logging.register-shutdown-hook";
125	
126		/**
127		 * The name of the {@link LoggingSystem} bean.
128		 */
129		public static final String LOGGING_SYSTEM_BEAN_NAME = "springBootLoggingSystem";
130	
131		/**
132		 * The name of the {@link LogFile} bean.
133		 * @since 2.2.0
134		 */
135		public static final String LOG_FILE_BEAN_NAME = "springBootLogFile";
136	
137		/**
138		 * The name of the {@link LoggerGroups} bean.
139		 * @since 2.2.0
140		 */
141		public static final String LOGGER_GROUPS_BEAN_NAME = "springBootLoggerGroups";
142	
143		/**
144		 * The name of the {@link Lifecycle} bean used to handle cleanup.
145		 */
146		private static final String LOGGING_LIFECYCLE_BEAN_NAME = "springBootLoggingLifecycle";
147	
148		private static final Map<String, List<String>> DEFAULT_GROUP_LOGGERS;
149		static {
150			MultiValueMap<String, String> loggers = new LinkedMultiValueMap<>();
151			loggers.add("web", "org.springframework.core.codec");
152			loggers.add("web", "org.springframework.http");
153			loggers.add("web", "org.springframework.web");
154			loggers.add("web", "org.springframework.boot.actuate.endpoint.web");
155			loggers.add("web", "org.springframework.boot.web.servlet.ServletContextInitializerBeans");
156			loggers.add("sql", "org.springframework.jdbc.core");
157			loggers.add("sql", "org.hibernate.SQL");
158			loggers.add("sql", "org.jooq.tools.LoggerListener");
159			DEFAULT_GROUP_LOGGERS = Collections.unmodifiableMap(loggers);
160		}
161	
162		private static final Map<LogLevel, List<String>> SPRING_BOOT_LOGGING_LOGGERS;
163		static {
164			MultiValueMap<LogLevel, String> loggers = new LinkedMultiValueMap<>();
165			loggers.add(LogLevel.DEBUG, "sql");
166			loggers.add(LogLevel.DEBUG, "web");
167			loggers.add(LogLevel.DEBUG, "org.springframework.boot");
168			loggers.add(LogLevel.TRACE, "org.springframework");
169			loggers.add(LogLevel.TRACE, "org.apache.tomcat");
170			loggers.add(LogLevel.TRACE, "org.apache.catalina");
171			loggers.add(LogLevel.TRACE, "org.eclipse.jetty");
172			loggers.add(LogLevel.TRACE, "org.hibernate.tool.hbm2ddl");
173			SPRING_BOOT_LOGGING_LOGGERS = Collections.unmodifiableMap(loggers);
174		}
175	
176		private static final Class<?>[] EVENT_TYPES = { ApplicationStartingEvent.class,
177				ApplicationEnvironmentPreparedEvent.class, ApplicationPreparedEvent.class, ContextClosedEvent.class,
178				ApplicationFailedEvent.class };
179	
180		private static final Class<?>[] SOURCE_TYPES = { SpringApplication.class, ApplicationContext.class };
181	
182		private static final AtomicBoolean shutdownHookRegistered = new AtomicBoolean();
183	
184		private final Log logger = LogFactory.getLog(getClass());
185	
186		private @Nullable LoggingSystem loggingSystem;
187	
188		private @Nullable LogFile logFile;
189	
190		private @Nullable LoggerGroups loggerGroups;
191	
192		private int order = DEFAULT_ORDER;
193	
194		private boolean parseArgs = true;
195	
196		private @Nullable LogLevel springBootLogging;
197	
198		@Override
199		public boolean supportsEventType(ResolvableType resolvableType) {
200			return isAssignableFrom(resolvableType.getRawClass(), EVENT_TYPES);
201		}
202	
203		@Override
204		public boolean supportsSourceType(@Nullable Class<?> sourceType) {
205			return isAssignableFrom(sourceType, SOURCE_TYPES);
206		}
207	
208		private boolean isAssignableFrom(@Nullable Class<?> type, Class<?>... supportedTypes) {
209			if (type != null) {
210				for (Class<?> supportedType : supportedTypes) {
211					if (supportedType.isAssignableFrom(type)) {
212						return true;
213					}
214				}
215			}
216			return false;
217		}
218	
219		@Override
220		public void onApplicationEvent(ApplicationEvent event) {
221			if (event instanceof ApplicationStartingEvent startingEvent) {
222				onApplicationStartingEvent(startingEvent);
223			}
224			else if (event instanceof ApplicationEnvironmentPreparedEvent environmentPreparedEvent) {
225				onApplicationEnvironmentPreparedEvent(environmentPreparedEvent);
226			}
227			else if (event instanceof ApplicationPreparedEvent preparedEvent) {
228				onApplicationPreparedEvent(preparedEvent);
229			}
230			else if (event instanceof ContextClosedEvent contextClosedEvent) {
231				onContextClosedEvent(contextClosedEvent);
232			}
233			else if (event instanceof ApplicationFailedEvent) {
234				onApplicationFailedEvent();
235			}
236		}
237	
238		private void onApplicationStartingEvent(ApplicationStartingEvent event) {
239			this.loggingSystem = LoggingSystem.get(event.getSpringApplication().getClassLoader());
240			this.loggingSystem.beforeInitialize();
241		}
242	
243		private void onApplicationEnvironmentPreparedEvent(ApplicationEnvironmentPreparedEvent event) {
244			SpringApplication springApplication = event.getSpringApplication();
245			if (this.loggingSystem == null) {
246				this.loggingSystem = LoggingSystem.get(springApplication.getClassLoader());
247			}
248			initialize(event.getEnvironment(), springApplication.getClassLoader());
249		}
250	
251		private void onApplicationPreparedEvent(ApplicationPreparedEvent event) {
252			ConfigurableApplicationContext applicationContext = event.getApplicationContext();
253			ConfigurableListableBeanFactory beanFactory = applicationContext.getBeanFactory();
254			if (!beanFactory.containsBean(LOGGING_SYSTEM_BEAN_NAME)) {
255				Assert.state(this.loggingSystem != null, "loggingSystem is not set");
256				beanFactory.registerSingleton(LOGGING_SYSTEM_BEAN_NAME, this.loggingSystem);
257			}
258			if (this.logFile != null && !beanFactory.containsBean(LOG_FILE_BEAN_NAME)) {
259				beanFactory.registerSingleton(LOG_FILE_BEAN_NAME, this.logFile);
260			}
261			if (this.loggerGroups != null && !beanFactory.containsBean(LOGGER_GROUPS_BEAN_NAME)) {
262				beanFactory.registerSingleton(LOGGER_GROUPS_BEAN_NAME, this.loggerGroups);
263			}
264			if (!beanFactory.containsBean(LOGGING_LIFECYCLE_BEAN_NAME) && applicationContext.getParent() == null) {
265				beanFactory.registerSingleton(LOGGING_LIFECYCLE_BEAN_NAME, new Lifecycle());
266			}
267		}
268	
269		private void onContextClosedEvent(ContextClosedEvent event) {
270			ApplicationContext applicationContext = event.getApplicationContext();
271			if (applicationContext.getParent() != null || applicationContext.containsBean(LOGGING_LIFECYCLE_BEAN_NAME)) {
272				return;
273			}
274			cleanupLoggingSystem();
275		}
276	
277		void cleanupLoggingSystem() {
278			if (this.loggingSystem != null) {
279				this.loggingSystem.cleanUp();
280			}
281		}
282	
283		private void onApplicationFailedEvent() {
284			cleanupLoggingSystem();
285		}
286	
287		/**
288		 * Initialize the logging system according to preferences expressed through the
289		 * {@link Environment} and the classpath.
290		 * @param environment the environment
291		 * @param classLoader the classloader
292		 */
293		protected void initialize(ConfigurableEnvironment environment, ClassLoader classLoader) {
294			getLoggingSystemProperties(environment).apply();
295			this.logFile = LogFile.get(environment);
296			if (this.logFile != null) {
297				this.logFile.applyToSystemProperties();
298			}
299			this.loggerGroups = new LoggerGroups(DEFAULT_GROUP_LOGGERS);
300			initializeEarlyLoggingLevel(environment);
301			Assert.state(this.loggingSystem != null, "loggingSystem is not set");
302			initializeSystem(environment, this.loggingSystem, this.logFile);
303			initializeFinalLoggingLevels(environment, this.loggingSystem);
304			registerShutdownHookIfNecessary(environment, this.loggingSystem);
305		}
306	
307		private LoggingSystemProperties getLoggingSystemProperties(ConfigurableEnvironment environment) {
308			return (this.loggingSystem != null) ? this.loggingSystem.getSystemProperties(environment)
309					: new LoggingSystemProperties(environment);
310		}
311	
312		private void initializeEarlyLoggingLevel(ConfigurableEnvironment environment) {
313			if (this.parseArgs && this.springBootLogging == null) {
314				if (isSet(environment, "debug")) {
315					this.springBootLogging = LogLevel.DEBUG;
316				}
317				if (isSet(environment, "trace")) {
318					this.springBootLogging = LogLevel.TRACE;
319				}
320			}
321		}
322	
323		private boolean isSet(ConfigurableEnvironment environment, String property) {
324			String value = environment.getProperty(property);
325			return (value != null && !value.equals("false"));
326		}
327	
328		private void initializeSystem(ConfigurableEnvironment environment, LoggingSystem system,
329				@Nullable LogFile logFile) {
330			String logConfig = environment.getProperty(CONFIG_PROPERTY);
331			if (StringUtils.hasLength(logConfig)) {
332				logConfig = logConfig.strip();
333			}
334			try {
335				LoggingInitializationContext initializationContext = new LoggingInitializationContext(environment);
336				if (ignoreLogConfig(logConfig)) {
337					system.initialize(initializationContext, null, logFile);
338				}
339				else {
340					system.initialize(initializationContext, logConfig, logFile);
341				}
342			}
343			catch (Throwable ex) {
344				Throwable exceptionToReport = ex;
345				while (exceptionToReport != null && !(exceptionToReport instanceof FileNotFoundException)) {
346					exceptionToReport = exceptionToReport.getCause();
347				}
348				exceptionToReport = (exceptionToReport != null) ? exceptionToReport : ex;
349				// NOTE: We can't use the logger here to report the problem
350				System.err.println("Logging system failed to initialize using configuration from '" + logConfig + "'");
351				exceptionToReport.printStackTrace(System.err);
352				throw new IllegalStateException(ex);
353			}
354		}
355	
356		private boolean ignoreLogConfig(@Nullable String logConfig) {
357			return !StringUtils.hasLength(logConfig) || logConfig.startsWith("-D");
358		}
359	
360		private void initializeFinalLoggingLevels(ConfigurableEnvironment environment, LoggingSystem system) {
361			bindLoggerGroups(environment);
362			if (this.springBootLogging != null) {
363				initializeSpringBootLogging(system, this.springBootLogging);
364			}
365			setLogLevels(system, environment);
366		}
367	
368		private void bindLoggerGroups(ConfigurableEnvironment environment) {
369			if (this.loggerGroups != null) {
370				Binder binder = Binder.get(environment);
371				binder.bind(LOGGING_GROUP, STRING_STRINGS_MAP).ifBound(this.loggerGroups::putAll);
372			}
373		}
374	
375		/**
376		 * Initialize loggers based on the {@link #setSpringBootLogging(LogLevel)
377		 * springBootLogging} setting. By default this implementation will pick an appropriate
378		 * set of loggers to configure based on the level.
379		 * @param system the logging system
380		 * @param springBootLogging the spring boot logging level requested
381		 * @since 2.2.0
382		 */
383		protected void initializeSpringBootLogging(LoggingSystem system, LogLevel springBootLogging) {
384			BiConsumer<String, @Nullable LogLevel> configurer = getLogLevelConfigurer(system);
385			SPRING_BOOT_LOGGING_LOGGERS.getOrDefault(springBootLogging, Collections.emptyList())
386				.forEach((name) -> configureLogLevel(name, springBootLogging, configurer));
387		}
388	
389		/**
390		 * Set logging levels based on relevant {@link Environment} properties.
391		 * @param system the logging system
392		 * @param environment the environment
393		 * @since 2.2.0
394		 */
395		protected void setLogLevels(LoggingSystem system, ConfigurableEnvironment environment) {
396			BiConsumer<String, @Nullable LogLevel> customizer = getLogLevelConfigurer(system);
397			Binder binder = Binder.get(environment);
398			Map<String, LogLevel> levels = binder.bind(LOGGING_LEVEL, STRING_LOGLEVEL_MAP).orElseGet(Collections::emptyMap);
399			levels.forEach((name, level) -> configureLogLevel(name, level, customizer));
400		}
401	
402		private void configureLogLevel(String name, LogLevel level, BiConsumer<String, @Nullable LogLevel> configurer) {
403			if (this.loggerGroups != null) {
404				LoggerGroup group = this.loggerGroups.get(name);
405				if (group != null && group.hasMembers()) {
406					group.configureLogLevel(level, configurer);
407					return;
408				}
409			}
410			configurer.accept(name, level);
411		}
412	
413		private BiConsumer<String, @Nullable LogLevel> getLogLevelConfigurer(LoggingSystem system) {
414			return (name, level) -> {
415				try {
416					name = name.equalsIgnoreCase(LoggingSystem.ROOT_LOGGER_NAME) ? null : name;
417					system.setLogLevel(name, level);
418				}
419				catch (RuntimeException ex) {
420					this.logger.error(LogMessage.format("Cannot set level '%s' for '%s'", level, name));
421				}
422			};
423		}
424	
425		private void registerShutdownHookIfNecessary(Environment environment, LoggingSystem loggingSystem) {
426			if (environment.getProperty(REGISTER_SHUTDOWN_HOOK_PROPERTY, Boolean.class, true)) {
427				Runnable shutdownHandler = loggingSystem.getShutdownHandler();
428				if (shutdownHandler != null && shutdownHookRegistered.compareAndSet(false, true)) {
429					registerShutdownHook(shutdownHandler);
430				}
431			}
432		}
433	
434		void registerShutdownHook(Runnable shutdownHandler) {
435			SpringApplication.getShutdownHandlers().add(shutdownHandler);
436		}
437	
438		public void setOrder(int order) {
439			this.order = order;
440		}
441	
442		@Override
443		public int getOrder() {
444			return this.order;
445		}
446	
447		/**
448		 * Sets a custom logging level to be used for Spring Boot and related libraries.
449		 * @param springBootLogging the logging level
450		 */
451		public void setSpringBootLogging(LogLevel springBootLogging) {
452			this.springBootLogging = springBootLogging;
453		}
454	
455		/**
456		 * Sets if initialization arguments should be parsed for {@literal debug} and
457		 * {@literal trace} properties (usually defined from {@literal --debug} or
458		 * {@literal --trace} command line args). Defaults to {@code true}.
459		 * @param parseArgs if arguments should be parsed
460		 */
461		public void setParseArgs(boolean parseArgs) {
462			this.parseArgs = parseArgs;
463		}
464	
465		private final class Lifecycle implements SmartLifecycle {
466	
467			private volatile boolean running;
468	
469			@Override
470			public void start() {
471				this.running = true;
472			}
473	
474			@Override
475			public void stop() {
476				this.running = false;
477				cleanupLoggingSystem();
478			}
479	
480			@Override
481			public boolean isRunning() {
482				return this.running;
483			}
484	
485			@Override
486			public int getPhase() {
487				// Shutdown late and always after WebServerStartStopLifecycle
488				return Integer.MIN_VALUE + 1;
489			}
490	
491		}
492	
493	}
