17	package org.springframework.boot.logging;
18	
19	import java.io.IOException;
20	import java.util.Arrays;
21	import java.util.Collections;
22	import java.util.EnumSet;
23	import java.util.HashSet;
24	import java.util.IdentityHashMap;
25	import java.util.Objects;
26	import java.util.Set;
27	import java.util.function.BiPredicate;
28	import java.util.function.Function;
29	import java.util.function.Predicate;
30	import java.util.function.ToIntFunction;
31	
32	import org.jspecify.annotations.Nullable;
33	
34	import org.springframework.util.Assert;
35	
36	/**
37	 * {@link StackTracePrinter} that prints a standard form stack trace. This printer
38	 * produces a result in a similar form to {@link Throwable#printStackTrace()}, but offers
39	 * more customization options.
40	 *
41	 * @author Phillip Webb
42	 * @since 3.5.0
43	 */
44	public final class StandardStackTracePrinter implements StackTracePrinter {
45	
46		private static final String DEFAULT_LINE_SEPARATOR = System.lineSeparator();
47	
48		private static final ToIntFunction<StackTraceElement> DEFAULT_FRAME_HASHER = (frame) -> Objects
49			.hash(frame.getClassName(), frame.getMethodName(), frame.getLineNumber());
50	
51		private static final int UNLIMITED = Integer.MAX_VALUE;
52	
53		private final EnumSet<Option> options;
54	
55		private final int maximumLength;
56	
57		private final String lineSeparator;
58	
59		private final Predicate<Throwable> filter;
60	
61		private final BiPredicate<Integer, StackTraceElement> frameFilter;
62	
63		private final Function<Throwable, String> formatter;
64	
65		private final Function<StackTraceElement, String> frameFormatter;
66	
67		private final @Nullable ToIntFunction<StackTraceElement> frameHasher;
68	
69		private StandardStackTracePrinter(EnumSet<Option> options, int maximumLength, @Nullable String lineSeparator,
70				@Nullable Predicate<Throwable> filter, @Nullable BiPredicate<Integer, StackTraceElement> frameFilter,
71				@Nullable Function<Throwable, String> formatter,
72				@Nullable Function<StackTraceElement, String> frameFormatter,
73				@Nullable ToIntFunction<StackTraceElement> frameHasher) {
74			this.options = options;
75			this.maximumLength = maximumLength;
76			this.lineSeparator = (lineSeparator != null) ? lineSeparator : DEFAULT_LINE_SEPARATOR;
77			this.filter = (filter != null) ? filter : (t) -> true;
78			this.frameFilter = (frameFilter != null) ? frameFilter : (i, t) -> true;
79			this.formatter = (formatter != null) ? formatter : Object::toString;
80			this.frameFormatter = (frameFormatter != null) ? frameFormatter : Object::toString;
81			this.frameHasher = frameHasher;
82		}
83	
84		@Override
85		public void printStackTrace(Throwable throwable, Appendable out) throws IOException {
86			if (this.filter.test(throwable)) {
87				Set<Throwable> seen = Collections.newSetFromMap(new IdentityHashMap<>());
88				Output output = new Output(out);
89				Print print = new Print("", "", output);
90				printFullStackTrace(seen, print, new StackTrace(throwable), null);
91			}
92		}
93	
94		private void printFullStackTrace(Set<Throwable> seen, Print print, @Nullable StackTrace stackTrace,
95				@Nullable StackTrace enclosing) throws IOException {
96			if (stackTrace == null) {
97				return;
98			}
99			if (!seen.add(stackTrace.throwable())) {
100				String hashPrefix = stackTrace.hashPrefix(this.frameHasher);
101				String throwable = this.formatter.apply(stackTrace.throwable());
102				print.circularReference(hashPrefix, throwable);
103				return;
104			}
105			StackTrace cause = stackTrace.cause();
106			if (!hasOption(Option.ROOT_FIRST)) {
107				printSingleStackTrace(seen, print, stackTrace, enclosing);
108				printFullStackTrace(seen, print.withCausedByCaption(cause), cause, stackTrace);
109			}
110			else {
111				printFullStackTrace(seen, print, cause, stackTrace);
112				printSingleStackTrace(seen, print.withWrappedByCaption(cause), stackTrace, enclosing);
113			}
114		}
115	
116		private void printSingleStackTrace(Set<Throwable> seen, Print print, StackTrace stackTrace,
117				@Nullable StackTrace enclosing) throws IOException {
118			String hashPrefix = stackTrace.hashPrefix(this.frameHasher);
119			String throwable = this.formatter.apply(stackTrace.throwable());
120			print.thrown(hashPrefix, throwable);
121			printFrames(print, stackTrace, enclosing);
122			if (!hasOption(Option.HIDE_SUPPRESSED)) {
123				StackTrace[] suppressed = stackTrace.suppressed();
124				if (suppressed != null) {
125					for (StackTrace suppressedStackTrace : suppressed) {
126						printFullStackTrace(seen, print.withSuppressedCaption(), suppressedStackTrace, stackTrace);
127					}
128				}
129			}
130		}
131	
132		private void printFrames(Print print, StackTrace stackTrace, @Nullable StackTrace enclosing) throws IOException {
133			int commonFrames = (!hasOption(Option.SHOW_COMMON_FRAMES)) ? stackTrace.commonFramesCount(enclosing) : 0;
134			int filteredFrames = 0;
135			StackTraceElement[] frames = stackTrace.frames();
136			if (frames != null) {
137				for (int i = 0; i < frames.length - commonFrames; i++) {
138					StackTraceElement element = frames[i];
139					if (!this.frameFilter.test(i, element)) {
140						filteredFrames++;
141						continue;
142					}
143					print.omittedFilteredFrames(filteredFrames);
144					filteredFrames = 0;
145					print.at(this.frameFormatter.apply(element));
146				}
147			}
148			print.omittedFilteredFrames(filteredFrames);
149			if (commonFrames != 0) {
150				print.omittedCommonFrames(commonFrames);
151			}
152		}
153	
154		/**
155		 * Return a new {@link StandardStackTracePrinter} from this one that will print all
156		 * common frames rather than replacing them with the {@literal "... N more"} message.
157		 * @return a new {@link StandardStackTracePrinter} instance
158		 */
159		public StandardStackTracePrinter withCommonFrames() {
160			return withOption(Option.SHOW_COMMON_FRAMES);
161		}
162	
163		/**
164		 * Return a new {@link StandardStackTracePrinter} from this one that will not print
165		 * {@link Throwable#getSuppressed() suppressed} items.
166		 * @return a new {@link StandardStackTracePrinter} instance
167		 */
168		public StandardStackTracePrinter withoutSuppressed() {
169			return withOption(Option.HIDE_SUPPRESSED);
170		}
171	
172		/**
173		 * Return a new {@link StandardStackTracePrinter} from this one that will use ellipses
174		 * to truncate output longer than the specified length.
175		 * @param maximumLength the maximum length that can be printed
176		 * @return a new {@link StandardStackTracePrinter} instance
177		 */
178		public StandardStackTracePrinter withMaximumLength(int maximumLength) {
179			Assert.isTrue(maximumLength > 0, "'maximumLength' must be positive");
180			return new StandardStackTracePrinter(this.options, maximumLength, this.lineSeparator, this.filter,
181					this.frameFilter, this.formatter, this.frameFormatter, this.frameHasher);
182		}
183	
184		/**
185		 * Return a new {@link StandardStackTracePrinter} from this one that filters frames
186		 * (including caused and suppressed) deeper than the specified maximum.
187		 * @param maximumThrowableDepth the maximum throwable depth
188		 * @return a new {@link StandardStackTracePrinter} instance
189		 */
190		public StandardStackTracePrinter withMaximumThrowableDepth(int maximumThrowableDepth) {
191			Assert.isTrue(maximumThrowableDepth > 0, "'maximumThrowableDepth' must be positive");
192			return withFrameFilter((index, element) -> index < maximumThrowableDepth);
193		}
194	
195		/**
196		 * Return a new {@link StandardStackTracePrinter} from this one that will only include
197		 * throwables (excluding caused and suppressed) that match the given predicate.
198		 * @param predicate the predicate used to filter the throwable
199		 * @return a new {@link StandardStackTracePrinter} instance
200		 */
201		public StandardStackTracePrinter withFilter(Predicate<Throwable> predicate) {
202			Assert.notNull(predicate, "'predicate' must not be null");
203			return new StandardStackTracePrinter(this.options, this.maximumLength, this.lineSeparator,
204					this.filter.and(predicate), this.frameFilter, this.formatter, this.frameFormatter, this.frameHasher);
205		}
206	
207		/**
208		 * Return a new {@link StandardStackTracePrinter} from this one that will only include
209		 * frames that match the given predicate.
210		 * @param predicate the predicate used to filter frames
211		 * @return a new {@link StandardStackTracePrinter} instance
212		 */
213		public StandardStackTracePrinter withFrameFilter(BiPredicate<Integer, StackTraceElement> predicate) {
214			Assert.notNull(predicate, "'predicate' must not be null");
215			return new StandardStackTracePrinter(this.options, this.maximumLength, this.lineSeparator, this.filter,
216					this.frameFilter.and(predicate), this.formatter, this.frameFormatter, this.frameHasher);
217		}
218	
219		/**
220		 * Return a new {@link StandardStackTracePrinter} from this one that prints the stack
221		 * trace using the specified line separator.
222		 * @param lineSeparator the line separator to use
223		 * @return a new {@link StandardStackTracePrinter} instance
224		 */
225		public StandardStackTracePrinter withLineSeparator(String lineSeparator) {
226			Assert.notNull(lineSeparator, "'lineSeparator' must not be null");
227			return new StandardStackTracePrinter(this.options, this.maximumLength, lineSeparator, this.filter,
228					this.frameFilter, this.formatter, this.frameFormatter, this.frameHasher);
229		}
230	
231		/**
232		 * Return a new {@link StandardStackTracePrinter} from this one that uses the
233		 * specified formatter to create a string representation of a throwable.
234		 * @param formatter the formatter to use
235		 * @return a new {@link StandardStackTracePrinter} instance
236		 * @see #withLineSeparator(String)
237		 */
238		public StandardStackTracePrinter withFormatter(Function<Throwable, String> formatter) {
239			Assert.notNull(formatter, "'formatter' must not be null");
240			return new StandardStackTracePrinter(this.options, this.maximumLength, this.lineSeparator, this.filter,
241					this.frameFilter, formatter, this.frameFormatter, this.frameHasher);
242		}
243	
244		/**
245		 * Return a new {@link StandardStackTracePrinter} from this one that uses the
246		 * specified formatter to create a string representation of a frame.
247		 * @param frameFormatter the frame formatter to use
248		 * @return a new {@link StandardStackTracePrinter} instance
249		 * @see #withLineSeparator(String)
250		 */
251		public StandardStackTracePrinter withFrameFormatter(Function<StackTraceElement, String> frameFormatter) {
252			Assert.notNull(frameFormatter, "'frameFormatter' must not be null");
253			return new StandardStackTracePrinter(this.options, this.maximumLength, this.lineSeparator, this.filter,
254					this.frameFilter, this.formatter, frameFormatter, this.frameHasher);
255		}
256	
257		/**
258		 * Return a new {@link StandardStackTracePrinter} from this one that generates and
259		 * prints hashes for each stacktrace.
260		 * @return a new {@link StandardStackTracePrinter} instance
261		 */
262		public StandardStackTracePrinter withHashes() {
263			return withHashes(true);
264		}
265	
266		/**
267		 * Return a new {@link StandardStackTracePrinter} from this one that changes if hashes
268		 * should be generated and printed for each stacktrace.
269		 * @param hashes if hashes should be added
270		 * @return a new {@link StandardStackTracePrinter} instance
271		 */
272		public StandardStackTracePrinter withHashes(boolean hashes) {
273			return withHashes((!hashes) ? null : DEFAULT_FRAME_HASHER);
274		}
275	
276		public StandardStackTracePrinter withHashes(@Nullable ToIntFunction<StackTraceElement> frameHasher) {
277			return new StandardStackTracePrinter(this.options, this.maximumLength, this.lineSeparator, this.filter,
278					this.frameFilter, this.formatter, this.frameFormatter, frameHasher);
279		}
280	
281		private StandardStackTracePrinter withOption(Option option) {
282			EnumSet<Option> options = EnumSet.copyOf(this.options);
283			options.add(option);
284			return new StandardStackTracePrinter(options, this.maximumLength, this.lineSeparator, this.filter,
285					this.frameFilter, this.formatter, this.frameFormatter, this.frameHasher);
286		}
287	
288		private boolean hasOption(Option option) {
289			return this.options.contains(option);
290		}
291	
292		/**
293		 * Return a {@link StandardStackTracePrinter} that prints the stack trace with the
294		 * root exception last (the same as {@link Throwable#printStackTrace()}).
295		 * @return a {@link StandardStackTracePrinter} that prints the stack trace root last
296		 */
297		public static StandardStackTracePrinter rootLast() {
298			return new StandardStackTracePrinter(EnumSet.noneOf(Option.class), UNLIMITED, null, null, null, null, null,
299					null);
300		}
301	
302		/**
303		 * Return a {@link StandardStackTracePrinter} that prints the stack trace with the
304		 * root exception first (the opposite of {@link Throwable#printStackTrace()}).
305		 * @return a {@link StandardStackTracePrinter} that prints the stack trace root first
306		 */
307		public static StandardStackTracePrinter rootFirst() {
308			return new StandardStackTracePrinter(EnumSet.of(Option.ROOT_FIRST), UNLIMITED, null, null, null, null, null,
309					null);
310		}
311	
312		/**
313		 * Options supported by this printer.
314		 */
315		private enum Option {
316	
317			ROOT_FIRST, SHOW_COMMON_FRAMES, HIDE_SUPPRESSED
318	
319		}
320	
321		/**
322		 * Prints the actual line output.
323		 */
324		private record Print(String indent, String caption, Output output) {
325	
326			void circularReference(String hashPrefix, String throwable) throws IOException {
327				this.output.println(this.indent, this.caption + "[CIRCULAR REFERENCE: " + hashPrefix + throwable + "]");
328			}
329	
330			void thrown(String hashPrefix, String throwable) throws IOException {
331				this.output.println(this.indent, this.caption + hashPrefix + throwable);
332			}
333	
334			void at(String frame) throws IOException {
335				this.output.println(this.indent, "\tat " + frame);
336			}
337	
338			void omittedFilteredFrames(int filteredFrameCount) throws IOException {
339				if (filteredFrameCount > 0) {
340					this.output.println(this.indent, "\t... " + filteredFrameCount + " filtered");
341				}
342			}
343	
344			void omittedCommonFrames(int commonFrameCount) throws IOException {
345				this.output.println(this.indent, "\t... " + commonFrameCount + " more");
346			}
347	
348			Print withCausedByCaption(@Nullable StackTrace causedBy) {
349				return withCaption(causedBy != null, "", "Caused by: ");
350			}
351	
352			Print withWrappedByCaption(@Nullable StackTrace wrappedBy) {
353				return withCaption(wrappedBy != null, "", "Wrapped by: ");
354			}
355	
356			public Print withSuppressedCaption() {
357				return withCaption(true, "\t", "Suppressed: ");
358			}
359	
360			private Print withCaption(boolean test, String extraIndent, String caption) {
361				return (test) ? new Print(this.indent + extraIndent, caption, this.output) : this;
362			}
363	
364		}
365	
366		/**
367		 * Line-by-line output.
368		 */
369		private class Output {
370	
371			private static final String ELLIPSIS = "...";
372	
373			private final Appendable out;
374	
375			private int remaining;
376	
377			Output(Appendable out) {
378				this.out = out;
379				this.remaining = StandardStackTracePrinter.this.maximumLength - ELLIPSIS.length();
380			}
381	
382			void println(String indent, String string) throws IOException {
383				if (this.remaining > 0) {
384					String line = indent + string + StandardStackTracePrinter.this.lineSeparator;
385					if (line.length() > this.remaining) {
386						line = line.substring(0, this.remaining) + ELLIPSIS;
387					}
388					this.out.append(line);
389					this.remaining -= line.length();
390				}
391			}
392	
393		}
394	
395		/**
396		 * Holds the stacktrace for a specific throwable and caches things that are expensive
397		 * to calculate.
398		 */
399		private static final class StackTrace {
400	
401			private final Throwable throwable;
402	
403			private final StackTraceElement @Nullable [] frames;
404	
405			private StackTrace @Nullable [] suppressed;
406	
407			private @Nullable StackTrace cause;
408	
409			private @Nullable Integer hash;
410	
411			private @Nullable String hashPrefix;
412	
413			private StackTrace(Throwable throwable) {
414				this.throwable = throwable;
415				this.frames = (throwable != null) ? throwable.getStackTrace() : null;
416			}
417	
418			Throwable throwable() {
419				return this.throwable;
420			}
421	
422			StackTraceElement @Nullable [] frames() {
423				return this.frames;
424			}
425	
426			int commonFramesCount(@Nullable StackTrace other) {
427				if (other == null || this.frames == null || other.frames == null) {
428					return 0;
429				}
430				int index = this.frames.length - 1;
431				int otherIndex = other.frames.length - 1;
432				while (index >= 0 && otherIndex >= 0 && this.frames[index].equals(other.frames[otherIndex])) {
433					index--;
434					otherIndex--;
435				}
436				return this.frames.length - 1 - index;
437			}
438	
439			StackTrace @Nullable [] suppressed() {
440				if (this.suppressed == null && this.throwable != null) {
441					this.suppressed = Arrays.stream(this.throwable.getSuppressed())
442						.map(StackTrace::new)
443						.toArray(StackTrace[]::new);
444				}
445				return this.suppressed;
446			}
447	
448			@Nullable StackTrace cause() {
449				if (this.cause == null && this.throwable != null) {
450					Throwable cause = this.throwable.getCause();
451					this.cause = (cause != null) ? new StackTrace(cause) : null;
452				}
453				return this.cause;
454			}
455	
456			String hashPrefix(@Nullable ToIntFunction<StackTraceElement> frameHasher) {
457				if (frameHasher == null || throwable() == null) {
458					return "";
459				}
460				this.hashPrefix = (this.hashPrefix != null) ? this.hashPrefix
461						: String.format("<#%08x> ", hash(new HashSet<>(), frameHasher));
462				return this.hashPrefix;
463			}
464	
465			private int hash(HashSet<Throwable> seen, ToIntFunction<StackTraceElement> frameHasher) {
466				if (this.hash != null) {
467					return this.hash;
468				}
469				int hash = 0;
470				StackTrace cause = cause();
471				if (cause != null && seen.add(cause.throwable())) {
472					hash = cause.hash(seen, frameHasher);
473				}
474				hash = 31 * hash + throwable().getClass().getName().hashCode();
475				if (frames() != null) {
476					for (StackTraceElement frame : frames()) {
477						hash = 31 * hash + frameHasher.applyAsInt(frame);
478					}
479				}
480				this.hash = hash;
481				return hash;
482			}
483	
484		}
485	
486	}
