17	package org.springframework.boot.context.properties.bind;
18	
19	import java.lang.annotation.Annotation;
20	import java.lang.reflect.Array;
21	import java.lang.reflect.Constructor;
22	import java.lang.reflect.Method;
23	import java.lang.reflect.Modifier;
24	import java.lang.reflect.Parameter;
25	import java.util.ArrayList;
26	import java.util.Collection;
27	import java.util.Collections;
28	import java.util.EnumMap;
29	import java.util.List;
30	import java.util.Map;
31	import java.util.Optional;
32	import java.util.concurrent.ConcurrentHashMap;
33	import java.util.function.Consumer;
34	
35	import kotlin.reflect.KFunction;
36	import kotlin.reflect.KParameter;
37	import kotlin.reflect.jvm.ReflectJvmMapping;
38	import org.apache.commons.logging.Log;
39	import org.apache.commons.logging.LogFactory;
40	import org.jspecify.annotations.Nullable;
41	
42	import org.springframework.beans.BeanUtils;
43	import org.springframework.boot.context.properties.bind.Binder.Context;
44	import org.springframework.boot.context.properties.source.ConfigurationPropertyName;
45	import org.springframework.core.CollectionFactory;
46	import org.springframework.core.DefaultParameterNameDiscoverer;
47	import org.springframework.core.KotlinDetector;
48	import org.springframework.core.MethodParameter;
49	import org.springframework.core.ParameterNameDiscoverer;
50	import org.springframework.core.ResolvableType;
51	import org.springframework.core.annotation.MergedAnnotation;
52	import org.springframework.core.annotation.MergedAnnotations;
53	import org.springframework.core.convert.ConversionException;
54	import org.springframework.core.log.LogMessage;
55	import org.springframework.util.Assert;
56	
57	/**
58	 * {@link DataObjectBinder} for immutable value objects.
59	 *
60	 * @author Madhura Bhave
61	 * @author Stephane Nicoll
62	 * @author Phillip Webb
63	 * @author Scott Frederick
64	 * @author Ondřej Světlík
65	 */
66	class ValueObjectBinder implements DataObjectBinder {
67	
68		private static final Log logger = LogFactory.getLog(ValueObjectBinder.class);
69	
70		private final BindConstructorProvider constructorProvider;
71	
72		ValueObjectBinder(BindConstructorProvider constructorProvider) {
73			this.constructorProvider = constructorProvider;
74		}
75	
76		@Override
77		public <T> @Nullable T bind(ConfigurationPropertyName name, Bindable<T> target, Binder.Context context,
78				DataObjectPropertyBinder propertyBinder, boolean fallbackToDefaultValue) {
79			ValueObject<T> valueObject = ValueObject.get(target, context, this.constructorProvider, Discoverer.LENIENT);
80			if (valueObject != null) {
81				Class<?> targetType = target.getType().resolve();
82				Assert.state(targetType != null, "'targetType' must not be null");
83				context.pushConstructorBoundTypes(targetType);
84				List<ConstructorParameter> parameters = valueObject.getConstructorParameters();
85				List<@Nullable Object> args = new ArrayList<>(parameters.size());
86				boolean bound = false;
87				for (ConstructorParameter parameter : parameters) {
88					Object arg = parameter.bind(propertyBinder);
89					bound = bound || arg != null;
90					arg = (arg != null) ? arg : getDefaultValue(context, parameter);
91					args.add(arg);
92				}
93				context.clearConfigurationProperty();
94				context.popConstructorBoundTypes();
95				if (bound) {
96					return valueObject.instantiate(args);
97				}
98			}
99			if (fallbackToDefaultValue) {
100				return getNewDefaultValueInstanceIfPossible(context, target.getType());
101			}
102			return null;
103		}
104	
105		@Override
106		public <T> @Nullable T create(Bindable<T> target, Binder.Context context) {
107			ValueObject<T> valueObject = ValueObject.get(target, context, this.constructorProvider, Discoverer.LENIENT);
108			if (valueObject == null) {
109				return null;
110			}
111			List<ConstructorParameter> parameters = valueObject.getConstructorParameters();
112			List<@Nullable Object> args = new ArrayList<>(parameters.size());
113			for (ConstructorParameter parameter : parameters) {
114				args.add(getDefaultValue(context, parameter));
115			}
116			return valueObject.instantiate(args);
117		}
118	
119		@Override
120		public <T> void onUnableToCreateInstance(Bindable<T> target, Context context, RuntimeException exception) {
121			try {
122				ValueObject.get(target, context, this.constructorProvider, Discoverer.STRICT);
123			}
124			catch (Exception ex) {
125				exception.addSuppressed(ex);
126			}
127		}
128	
129		private <T> @Nullable T getDefaultValue(Binder.Context context, ConstructorParameter parameter) {
130			ResolvableType type = parameter.getType();
131			Annotation[] annotations = parameter.getAnnotations();
132			for (Annotation annotation : annotations) {
133				if (annotation instanceof DefaultValue defaultValueAnnotation) {
134					String[] defaultValue = defaultValueAnnotation.value();
135					if (defaultValue.length == 0) {
136						return getNewDefaultValueInstanceIfPossible(context, type);
137					}
138					return convertDefaultValue(context.getConverter(), defaultValue, type, annotations);
139				}
140			}
141			return context.getConverter().convert(null, type);
142		}
143	
144		private <T> @Nullable T convertDefaultValue(BindConverter converter, String[] defaultValue, ResolvableType type,
145				Annotation[] annotations) {
146			try {
147				return converter.convert(defaultValue, type, annotations);
148			}
149			catch (ConversionException ex) {
150				// Try again in case ArrayToObjectConverter is not in play
151				if (defaultValue.length == 1) {
152					return converter.convert(defaultValue[0], type, annotations);
153				}
154				throw ex;
155			}
156		}
157	
158		@SuppressWarnings("unchecked")
159		private <T> @Nullable T getNewDefaultValueInstanceIfPossible(Binder.Context context, ResolvableType type) {
160			Class<T> resolved = (Class<T>) type.resolve();
161			Assert.state(resolved == null || isEmptyDefaultValueAllowed(resolved),
162					() -> "Parameter of type " + type + " must have a non-empty default value.");
163			if (resolved != null) {
164				if (Optional.class == resolved) {
165					return (T) Optional.empty();
166				}
167				if (Collection.class.isAssignableFrom(resolved)) {
168					return (T) CollectionFactory.createCollection(resolved, 0);
169				}
170				if (EnumMap.class.isAssignableFrom(resolved)) {
171					Class<?> keyType = type.asMap().resolveGeneric(0);
172					return (T) CollectionFactory.createMap(resolved, keyType, 0);
173				}
174				if (Map.class.isAssignableFrom(resolved)) {
175					return (T) CollectionFactory.createMap(resolved, 0);
176				}
177				if (resolved.isArray()) {
178					return (T) Array.newInstance(resolved.getComponentType(), 0);
179				}
180			}
181			T instance = create(Bindable.of(type), context);
182			if (instance != null) {
183				return instance;
184			}
185			return (resolved != null) ? BeanUtils.instantiateClass(resolved) : null;
186		}
187	
188		private boolean isEmptyDefaultValueAllowed(Class<?> type) {
189			return (Optional.class == type || isAggregate(type))
190					|| !(type.isPrimitive() || type.isEnum() || type.getName().startsWith("java.lang"));
191		}
192	
193		private boolean isAggregate(Class<?> type) {
194			return type.isArray() || Map.class.isAssignableFrom(type) || Collection.class.isAssignableFrom(type);
195		}
196	
197		/**
198		 * The value object being bound.
199		 *
200		 * @param <T> the value object type
201		 */
202		private abstract static class ValueObject<T> {
203	
204			private static final Object NONE = new Object();
205	
206			private final Constructor<T> constructor;
207	
208			protected ValueObject(Constructor<T> constructor) {
209				this.constructor = constructor;
210			}
211	
212			T instantiate(List<@Nullable Object> args) {
213				return BeanUtils.instantiateClass(this.constructor, args.toArray());
214			}
215	
216			abstract List<ConstructorParameter> getConstructorParameters();
217	
218			@SuppressWarnings("unchecked")
219			static <T> @Nullable ValueObject<T> get(Bindable<T> bindable, Binder.Context context,
220					BindConstructorProvider constructorProvider, ParameterNameDiscoverer parameterNameDiscoverer) {
221				Class<T> resolvedType = (Class<T>) bindable.getType().resolve();
222				if (resolvedType == null || resolvedType.isEnum() || Modifier.isAbstract(resolvedType.getModifiers())) {
223					return null;
224				}
225				Map<CacheKey, Object> cache = getCache(context);
226				CacheKey cacheKey = new CacheKey(bindable, constructorProvider, parameterNameDiscoverer);
227				Object valueObject = cache.get(cacheKey);
228				if (valueObject == null) {
229					valueObject = get(bindable, context, constructorProvider, parameterNameDiscoverer, resolvedType);
230					cache.put(cacheKey, (valueObject != null) ? valueObject : NONE);
231				}
232				return (valueObject != NONE) ? (ValueObject<T>) valueObject : null;
233			}
234	
235			@SuppressWarnings("unchecked")
236			private static <T> @Nullable ValueObject<T> get(Bindable<T> bindable, Binder.Context context,
237					BindConstructorProvider constructorProvider, ParameterNameDiscoverer parameterNameDiscoverer,
238					Class<T> resolvedType) {
239				Constructor<?> bindConstructor = constructorProvider.getBindConstructor(bindable,
240						context.isNestedConstructorBinding());
241				if (bindConstructor == null) {
242					return null;
243				}
244				if (KotlinDetector.isKotlinType(resolvedType)) {
245					return KotlinValueObject.get((Constructor<T>) bindConstructor, bindable.getType(),
246							parameterNameDiscoverer);
247				}
248				return DefaultValueObject.get(bindConstructor, bindable.getType(), parameterNameDiscoverer);
249			}
250	
251			@SuppressWarnings("unchecked")
252			private static Map<CacheKey, Object> getCache(Context context) {
253				Map<CacheKey, Object> cache = (Map<CacheKey, Object>) context.getCache().get(ValueObject.class);
254				if (cache == null) {
255					cache = new ConcurrentHashMap<>();
256					context.getCache().put(ValueObject.class, cache);
257				}
258				return cache;
259			}
260	
261			private record CacheKey(Bindable<?> bindable, BindConstructorProvider constructorProvider,
262					ParameterNameDiscoverer parameterNameDiscoverer) {
263	
264			}
265	
266		}
267	
268		/**
269		 * A {@link ValueObject} implementation that is aware of Kotlin specific constructs.
270		 */
271		private static final class KotlinValueObject<T> extends ValueObject<T> {
272	
273			private static final Annotation[] ANNOTATION_ARRAY = new Annotation[0];
274	
275			private final List<ConstructorParameter> constructorParameters;
276	
277			private KotlinValueObject(Constructor<T> primaryConstructor, KFunction<T> kotlinConstructor,
278					ResolvableType type) {
279				super(primaryConstructor);
280				this.constructorParameters = parseConstructorParameters(kotlinConstructor, type);
281			}
282	
283			private List<ConstructorParameter> parseConstructorParameters(KFunction<T> kotlinConstructor,
284					ResolvableType type) {
285				List<KParameter> parameters = kotlinConstructor.getParameters();
286				List<ConstructorParameter> result = new ArrayList<>(parameters.size());
287				for (KParameter parameter : parameters) {
288					String name = getParameterName(parameter);
289					ResolvableType parameterType = ResolvableType
290						.forType(ReflectJvmMapping.getJavaType(parameter.getType()), type);
291					Annotation[] annotations = parameter.getAnnotations().toArray(ANNOTATION_ARRAY);
292					Assert.state(name != null, "'name' must not be null");
293					result.add(new ConstructorParameter(name, parameterType, annotations));
294				}
295				return Collections.unmodifiableList(result);
296			}
297	
298			private @Nullable String getParameterName(KParameter parameter) {
299				return MergedAnnotations.from(parameter, parameter.getAnnotations().toArray(ANNOTATION_ARRAY))
300					.get(Name.class)
301					.getValue(MergedAnnotation.VALUE, String.class)
302					.orElseGet(parameter::getName);
303			}
304	
305			@Override
306			List<ConstructorParameter> getConstructorParameters() {
307				return this.constructorParameters;
308			}
309	
310			static <T> @Nullable ValueObject<T> get(Constructor<T> bindConstructor, ResolvableType type,
311					ParameterNameDiscoverer parameterNameDiscoverer) {
312				KFunction<T> kotlinConstructor = ReflectJvmMapping.getKotlinFunction(bindConstructor);
313				if (kotlinConstructor != null) {
314					return new KotlinValueObject<>(bindConstructor, kotlinConstructor, type);
315				}
316				return DefaultValueObject.get(bindConstructor, type, parameterNameDiscoverer);
317			}
318	
319		}
320	
321		/**
322		 * A default {@link ValueObject} implementation that uses only standard Java
323		 * reflection calls.
324		 */
325		private static final class DefaultValueObject<T> extends ValueObject<T> {
326	
327			private final List<ConstructorParameter> constructorParameters;
328	
329			private DefaultValueObject(Constructor<T> constructor, List<ConstructorParameter> constructorParameters) {
330				super(constructor);
331				this.constructorParameters = constructorParameters;
332			}
333	
334			@Override
335			List<ConstructorParameter> getConstructorParameters() {
336				return this.constructorParameters;
337			}
338	
339			@SuppressWarnings("unchecked")
340			static <T> @Nullable ValueObject<T> get(Constructor<?> bindConstructor, ResolvableType type,
341					ParameterNameDiscoverer parameterNameDiscoverer) {
342				@Nullable String @Nullable [] names = parameterNameDiscoverer.getParameterNames(bindConstructor);
343				if (names == null) {
344					return null;
345				}
346				List<ConstructorParameter> constructorParameters = parseConstructorParameters(bindConstructor, type, names);
347				return new DefaultValueObject<>((Constructor<T>) bindConstructor, constructorParameters);
348			}
349	
350			private static List<ConstructorParameter> parseConstructorParameters(Constructor<?> constructor,
351					ResolvableType type, @Nullable String[] names) {
352				Parameter[] parameters = constructor.getParameters();
353				List<ConstructorParameter> result = new ArrayList<>(parameters.length);
354				for (int i = 0; i < parameters.length; i++) {
355					String name = MergedAnnotations.from(parameters[i])
356						.get(Name.class)
357						.getValue(MergedAnnotation.VALUE, String.class)
358						.orElse(names[i]);
359					ResolvableType parameterType = ResolvableType.forMethodParameter(new MethodParameter(constructor, i),
360							type);
361					Annotation[] annotations = parameters[i].getDeclaredAnnotations();
362					Assert.state(name != null, "'name' must not be null");
363					result.add(new ConstructorParameter(name, parameterType, annotations));
364				}
365				return Collections.unmodifiableList(result);
366			}
367	
368		}
369	
370		/**
371		 * A constructor parameter being bound.
372		 */
373		private static class ConstructorParameter {
374	
375			private final String name;
376	
377			private final ResolvableType type;
378	
379			private final Annotation[] annotations;
380	
381			ConstructorParameter(String name, ResolvableType type, Annotation[] annotations) {
382				this.name = DataObjectPropertyName.toDashedForm(name);
383				this.type = type;
384				this.annotations = annotations;
385			}
386	
387			@Nullable Object bind(DataObjectPropertyBinder propertyBinder) {
388				return propertyBinder.bindProperty(this.name, Bindable.of(this.type).withAnnotations(this.annotations));
389			}
390	
391			Annotation[] getAnnotations() {
392				return this.annotations;
393			}
394	
395			ResolvableType getType() {
396				return this.type;
397			}
398	
399		}
400	
401		/**
402		 * {@link ParameterNameDiscoverer} used for value data object binding.
403		 */
404		static final class Discoverer implements ParameterNameDiscoverer {
405	
406			private static final ParameterNameDiscoverer DEFAULT_DELEGATE = new DefaultParameterNameDiscoverer();
407	
408			private static final ParameterNameDiscoverer LENIENT = new Discoverer(DEFAULT_DELEGATE, (message) -> {
409			});
410	
411			private static final ParameterNameDiscoverer STRICT = new Discoverer(DEFAULT_DELEGATE, (message) -> {
412				throw new IllegalStateException(message.toString());
413			});
414	
415			private final ParameterNameDiscoverer delegate;
416	
417			private final Consumer<LogMessage> noParameterNamesHandler;
418	
419			private Discoverer(ParameterNameDiscoverer delegate, Consumer<LogMessage> noParameterNamesHandler) {
420				this.delegate = delegate;
421				this.noParameterNamesHandler = noParameterNamesHandler;
422			}
423	
424			@Override
425			public String[] getParameterNames(Method method) {
426				throw new UnsupportedOperationException();
427			}
428	
429			@Override
430			public @Nullable String @Nullable [] getParameterNames(Constructor<?> constructor) {
431				@Nullable String @Nullable [] names = this.delegate.getParameterNames(constructor);
432				if (names != null) {
433					return names;
434				}
435				LogMessage message = LogMessage.format(
436						"Unable to use value object binding with constructor [%s] as parameter names cannot be discovered. "
437								+ "Ensure that the compiler uses the '-parameters' flag",
438						constructor);
439				this.noParameterNamesHandler.accept(message);
440				logger.debug(message);
441				return null;
442			}
443	
444		}
445	
446	}
